package live

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
)

// Reminder replies are generated by the server. A model must never be allowed
// to claim a calendar write that did not commit.
const reminderQuestionPrefix = "我可以为你创建定时提醒"

type assistantReminder struct {
	Handled bool
	Title   string
	RunAt   time.Time
	Reply   string
}

var (
	reminderClock      = regexp.MustCompile(`(凌晨|早上|上午|中午|下午|傍晚|晚上|夜里)?\s*([0-9]{1,2}|[一二两三四五六七八九十]{1,3})\s*点\s*(半|一刻|三刻|(?:[0-9]{1,2}|[零〇一二两三四五六七八九十]{1,3})\s*分?)?`)
	reminderColonClock = regexp.MustCompile(`(?:^|[^0-9])([0-2]?[0-9]):([0-5][0-9])(?:$|[^0-9])`)
	reminderColonBare  = regexp.MustCompile(`[0-2]?[0-9]:[0-5][0-9]`)
	reminderAnyClock   = regexp.MustCompile(`(?:[0-9]{1,3}|[零〇一二两三四五六七八九十]{1,4})\s*点|[0-9]{1,2}:[0-9]{1,3}`)
	reminderISODate    = regexp.MustCompile(`([0-9]{4})[-/]([0-9]{1,2})[-/]([0-9]{1,2})`)
	reminderCNDate     = regexp.MustCompile(`(?:([0-9]{4})年)?([0-9]{1,2})月([0-9]{1,2})[日号]`)
	reminderWeekday    = regexp.MustCompile(`(下周|下星期|本周|这周|周|星期)([一二三四五六日天])`)
	reminderRelative   = regexp.MustCompile(`([0-9]{1,3}|[一二两三四五六七八九十半]+)\s*个?\s*(半)?\s*(小时|钟头|分钟)\s*(?:之?后|以后|后)?`)
)

func reminderIntent(prompt string) bool {
	if reminderCancellation(prompt) {
		return false
	}
	for _, phrase := range []string{"提醒我", "设置提醒", "创建提醒", "做个提醒", "安排提醒", "加到日程", "加入日程", "加入我的日程", "记到日程", "记到我的日程", "记在日程", "记上日程", "放到日程", "放进日程", "排到日程", "安排到日程", "安排到我的日程", "提上日程"} {
		if strings.Contains(prompt, phrase) {
			return true
		}
	}
	return false
}

func reminderCancellation(prompt string) bool {
	for _, phrase := range []string{"取消提醒", "删除提醒", "别提醒我", "不要提醒我", "不用提醒", "无需提醒"} {
		if strings.Contains(prompt, phrase) {
			return true
		}
	}
	return false
}

func reminderReferenceIntent(prompt string) bool {
	for _, phrase := range []string{"记到日程", "记到我的日程", "记在日程", "记上日程", "加到日程", "加入日程", "加入我的日程", "放到日程", "放进日程", "排到日程", "安排到日程", "安排到我的日程", "提上日程"} {
		if strings.Contains(prompt, phrase) {
			return true
		}
	}
	return false
}

func chineseHour(raw string) (int, bool) {
	if n, err := strconv.Atoi(raw); err == nil {
		return n, true
	}
	values := map[rune]int{'一': 1, '二': 2, '两': 2, '三': 3, '四': 4, '五': 5, '六': 6, '七': 7, '八': 8, '九': 9}
	r := []rune(raw)
	if raw == "十" {
		return 10, true
	}
	if len(r) == 2 && r[0] == '十' {
		return 10 + values[r[1]], values[r[1]] > 0
	}
	if len(r) == 2 && r[1] == '十' {
		return values[r[0]] * 10, values[r[0]] > 0
	}
	if len(r) == 3 && r[1] == '十' {
		return values[r[0]]*10 + values[r[2]], values[r[0]] > 0 && values[r[2]] > 0
	}
	if len(r) == 1 {
		return values[r[0]], values[r[0]] > 0
	}
	return 0, false
}

func parseReminderClock(raw string) (int, int, bool) {
	if indexes := reminderClock.FindStringSubmatchIndex(raw); indexes != nil {
		m := reminderClock.FindStringSubmatch(raw)
		if indexes[1] < len(raw) && strings.ContainsRune("0123456789零〇一二两三四五六七八九十半刻分", []rune(raw[indexes[1]:])[0]) {
			return 0, 0, false
		}
		hour, ok := chineseHour(m[2])
		if !ok || hour > 23 {
			return 0, 0, false
		}
		minute := 0
		if m[3] == "半" {
			minute = 30
		} else if m[3] == "一刻" {
			minute = 15
		} else if m[3] == "三刻" {
			minute = 45
		} else if m[3] != "" {
			minuteText := strings.TrimSpace(strings.TrimSuffix(m[3], "分"))
			var parseOK bool
			minute, parseOK = chineseHour(strings.TrimLeft(minuteText, "零〇"))
			if minuteText == "零" || minuteText == "〇" {
				minute, parseOK = 0, true
			}
			if !parseOK {
				return 0, 0, false
			}
		}
		if minute > 59 {
			return 0, 0, false
		}
		switch m[1] {
		case "下午", "傍晚", "晚上", "夜里":
			if hour < 12 {
				hour += 12
			}
		case "中午":
			if hour < 11 {
				hour += 12
			}
		case "凌晨":
			if hour == 12 {
				hour = 0
			}
		}
		return hour, minute, true
	}
	if m := reminderColonClock.FindStringSubmatch(raw); m != nil {
		hour, _ := strconv.Atoi(m[1])
		minute, _ := strconv.Atoi(m[2])
		if hour > 23 {
			return 0, 0, false
		}
		if strings.Contains(raw, "下午") || strings.Contains(raw, "晚上") {
			if hour < 12 {
				hour += 12
			}
		}
		return hour, minute, true
	}
	return 0, 0, false
}

// parseReminderRelative understands "一小时后", "半小时后", "一个半小时后"
// and "30分钟后" relative to the supplied local time.
func parseReminderRelative(raw string, now time.Time) (time.Time, bool) {
	m := reminderRelative.FindStringSubmatch(raw)
	if m == nil {
		return time.Time{}, false
	}
	numberText, half, unit := m[1], m[2] != "", m[3]
	minutes := 0
	if numberText == "半" {
		minutes = 30
		half = false
	} else {
		n, ok := chineseHour(numberText)
		if !ok || n <= 0 {
			return time.Time{}, false
		}
		if unit == "小时" || unit == "钟头" {
			minutes = n * 60
		} else {
			minutes = n
		}
	}
	if half && (unit == "小时" || unit == "钟头") {
		minutes += 30
	}
	if minutes <= 0 || minutes > 24*60 {
		return time.Time{}, false
	}
	return now.Add(time.Duration(minutes) * time.Minute), true
}

func reminderHasDate(raw string) bool {
	return reminderISODate.MatchString(raw) || reminderCNDate.MatchString(raw) || reminderWeekday.MatchString(raw) || strings.Contains(raw, "今天") || strings.Contains(raw, "今晚") || strings.Contains(raw, "今早") || strings.Contains(raw, "明天") || strings.Contains(raw, "明早") || strings.Contains(raw, "明晚") || strings.Contains(raw, "明日") || strings.Contains(raw, "后天")
}

func parseReminderDay(raw string, now time.Time) (time.Time, bool) {
	if m := reminderISODate.FindStringSubmatch(raw); m != nil {
		y, _ := strconv.Atoi(m[1])
		mo, _ := strconv.Atoi(m[2])
		d, _ := strconv.Atoi(m[3])
		day := time.Date(y, time.Month(mo), d, 0, 0, 0, 0, now.Location())
		return day, day.Year() == y && int(day.Month()) == mo && day.Day() == d
	}
	if m := reminderCNDate.FindStringSubmatch(raw); m != nil {
		y := now.Year()
		if m[1] != "" {
			y, _ = strconv.Atoi(m[1])
		}
		mo, _ := strconv.Atoi(m[2])
		d, _ := strconv.Atoi(m[3])
		day := time.Date(y, time.Month(mo), d, 0, 0, 0, 0, now.Location())
		if m[1] == "" && day.Before(now.AddDate(0, 0, -1)) {
			day = day.AddDate(1, 0, 0)
		}
		return day, int(day.Month()) == mo && day.Day() == d
	}
	if m := reminderWeekday.FindStringSubmatch(raw); m != nil {
		weekday := map[string]int{"一": 1, "二": 2, "三": 3, "四": 4, "五": 5, "六": 6, "日": 7, "天": 7}[m[2]]
		current := int(now.Weekday())
		if current == 0 {
			current = 7
		}
		offset := weekday - current
		switch m[1] {
		case "下周", "下星期":
			daysToNextMonday := 8 - current
			offset = daysToNextMonday + weekday - 1
		case "周", "星期":
			if offset < 0 {
				offset += 7
			}
		}
		return now.AddDate(0, 0, offset), true
	}
	if strings.Contains(raw, "后天") {
		return now.AddDate(0, 0, 2), true
	}
	if strings.Contains(raw, "明天") || strings.Contains(raw, "明早") || strings.Contains(raw, "明晚") || strings.Contains(raw, "明日") {
		return now.AddDate(0, 0, 1), true
	}
	if strings.Contains(raw, "今天") || strings.Contains(raw, "今晚") || strings.Contains(raw, "今早") {
		return now, true
	}
	return time.Time{}, false
}

func reminderTitle(raw string) string {
	title := strings.TrimSpace(raw)
	if i := strings.LastIndex(title, "就是"); i >= 0 {
		title = strings.TrimSpace(title[i+len("就是"):])
	}
	// The trigger can appear at the end ("……，到时候提醒我") or the beginning
	// ("提醒我明天开会"). Take the side that actually carries the task text.
	if i := strings.LastIndex(title, "提醒我"); i >= 0 {
		after := strings.TrimSpace(title[i+len("提醒我"):])
		if after == "" || reminderBlankText(after) {
			title = strings.TrimSpace(title[:i])
		} else {
			title = after
		}
	} else if i := strings.LastIndex(title, "提醒"); i >= 0 {
		after := strings.TrimSpace(title[i+len("提醒"):])
		if after != "" && !reminderBlankText(after) {
			title = after
		}
	}
	if strings.Contains(title, "把") {
		if i := strings.Index(title, "把"); i >= 0 {
			title = title[i+len("把"):]
		}
	}
	title = reminderISODate.ReplaceAllString(title, "")
	title = reminderCNDate.ReplaceAllString(title, "")
	title = reminderWeekday.ReplaceAllString(title, "")
	// Remove relative day words before clock patterns: the colon clock regex
	// consumes one preceding character, which would otherwise leave "明" in
	// "改为明天15:00".
	for _, phrase := range []string{"明天", "明早", "明晚", "明日", "后天", "今天", "今晚", "今早"} {
		title = strings.ReplaceAll(title, phrase, "")
	}
	title = reminderRelative.ReplaceAllString(title, "")
	title = reminderClock.ReplaceAllString(title, "")
	title = reminderColonBare.ReplaceAllString(title, "")
	for _, phrase := range []string{"加到我的日程上", "记到我的日程上", "放到我的日程上", "安排到我的日程", "记到我的日程", "加入我的日程", "加入日程", "加到日程", "记到日程", "记在日程", "记上日程", "设置提醒", "创建提醒", "做个提醒", "安排提醒", "放到日程", "放进日程", "排到日程", "安排到日程", "提上日程", "到时候", "的时候", "到时", "记得", "别忘了", "别忘", "麻烦", "有一个", "有个", "有一场", "有一项", "一下", "这个", "那个", "明天", "明早", "明晚", "明日", "后天", "今天", "今晚", "今早", "要干一个活", "要做一个事", "要做", "要干"} {
		title = strings.ReplaceAll(title, phrase, "")
	}
	for _, prefix := range []string{"请帮我", "帮我", "请", "我", "将"} {
		title = strings.TrimPrefix(strings.TrimSpace(title), prefix)
	}
	title = strings.Trim(title, " ，。！？!?,.：:；;、")
	// A bare adjustment refers to the pending reminder's title, not a new one:
	// "改为一个小时后" must reuse "会议" from the previous turn.
	switch title {
	case "改为", "改成", "改到", "改至", "延后", "推迟", "提前", "调整", "就", "那就":
		return ""
	}
	return title
}

// reminderBlankText reports whether the fragment only contains punctuation or
// connective filler left after the trigger phrase.
func reminderBlankText(value string) bool {
	return strings.Trim(value, " ，。！？!?,.：:；;、的时候到时记得一下下我") == ""
}

// planAssistantReminder reads conversation context to understand a follow-up
// such as “记到我的日程上” and a later answer such as “明天上午十点”.
func (s *Server) planAssistantReminder(ctx context.Context, conversationID, excludeMessageID, prompt, timezone string, now time.Time) (assistantReminder, error) {
	if reminderCancellation(prompt) {
		return assistantReminder{}, nil
	}
	rows, err := s.DB.QueryContext(ctx, `SELECT role,content FROM conversation_messages WHERE conversation_id=UNHEX(?) AND (?='' OR id<>UNHEX(?)) AND role IN ('user','assistant') ORDER BY created_at DESC,id DESC LIMIT 6`, conversationID, excludeMessageID, excludeMessageID)
	if err != nil {
		return assistantReminder{}, err
	}
	defer rows.Close()
	var history []struct{ role, content string }
	for rows.Next() {
		var item struct{ role, content string }
		if err = rows.Scan(&item.role, &item.content); err != nil {
			return assistantReminder{}, err
		}
		history = append(history, item)
	}
	if err = rows.Err(); err != nil {
		return assistantReminder{}, err
	}
	intent := reminderIntent(prompt)
	pending := len(history) > 0 && history[0].role == "assistant" && strings.HasPrefix(history[0].content, reminderQuestionPrefix)
	// Recover conversations where an older model promised a write without
	// actually creating a job. The next time the user supplies a clock we can
	// complete the action instead of repeating the false promise.
	legacyPending := false
	if len(history) >= 2 && history[0].role == "assistant" && strings.Contains(history[0].content, "日程") {
		for _, item := range history[1:] {
			if item.role == "user" {
				legacyPending = reminderIntent(item.content)
				break
			}
		}
	}
	pending = pending || legacyPending
	if !intent && !pending {
		return assistantReminder{}, nil
	}
	if pending && !intent {
		if strings.Contains(prompt, "算了") || strings.Contains(prompt, "取消") {
			return assistantReminder{}, nil
		}
		if _, _, ok := parseReminderClock(prompt); !ok && !reminderRelative.MatchString(prompt) && !strings.Contains(prompt, "日程") && !strings.Contains(prompt, "安排") && !strings.Contains(prompt, "记录") {
			return assistantReminder{}, nil
		}
	}
	loc, err := time.LoadLocation(timezone)
	if err != nil {
		return assistantReminder{}, err
	}
	localNow := now.In(loc)
	source := prompt
	if reminderTitle(prompt) == "" && (pending || reminderReferenceIntent(prompt)) {
		for _, item := range history {
			if item.role == "user" && reminderTitle(item.content) != "" {
				source = item.content
				break
			}
		}
	}
	title := reminderTitle(source)
	if title == "" || len([]rune(title)) > 160 {
		return assistantReminder{Handled: true, Reply: reminderQuestionPrefix + "。请告诉我要安排什么事情，以及日期和具体时间（例如：明天上午 10 点建立官网）。"}, nil
	}
	if relativeAt, relativeOK := parseReminderRelative(prompt, localNow); relativeOK {
		if relativeAt.After(localNow.AddDate(1, 0, 0)) {
			return assistantReminder{Handled: true, Title: title, Reply: reminderQuestionPrefix + "“" + title + "”，但这个时间超出了一年。请告诉我未来一年内的日期和时间。"}, nil
		}
		return assistantReminder{Handled: true, Title: title, RunAt: relativeAt.UTC(), Reply: fmt.Sprintf("已为你创建定时提醒：%s，%s（%s）。你可以在设置页查看；到时会收到站内通知。", title, relativeAt.Format("2006-01-02 15:04"), timezone)}, nil
	}
	day, dayOK := parseReminderDay(prompt, localNow)
	if !dayOK && !reminderHasDate(prompt) {
		day, dayOK = parseReminderDay(source, localNow)
	}
	hour, minute, clockOK := parseReminderClock(prompt)
	if !clockOK && !reminderAnyClock.MatchString(prompt) {
		hour, minute, clockOK = parseReminderClock(source)
	}
	if !dayOK || !clockOK {
		return assistantReminder{Handled: true, Title: title, Reply: reminderQuestionPrefix + "“" + title + "”。请告诉我具体日期和时间（例如：明天上午 10 点）；确认后我会保存并回报结果。"}, nil
	}
	runAt := time.Date(day.Year(), day.Month(), day.Day(), hour, minute, 0, 0, loc)
	localRunAt := runAt.In(loc)
	if localRunAt.Year() != day.Year() || localRunAt.Month() != day.Month() || localRunAt.Day() != day.Day() || localRunAt.Hour() != hour || localRunAt.Minute() != minute {
		return assistantReminder{Handled: true, Title: title, Reply: reminderQuestionPrefix + "“" + title + "”，但这个时间在你的时区不存在。请提供另一个具体时间。"}, nil
	}
	if runAt.Before(now.Add(time.Minute)) {
		if now.Sub(runAt) < 24*time.Hour {
			return assistantReminder{Handled: true, Title: title, Reply: reminderQuestionPrefix + "“" + title + "”的时间 " + runAt.Format("01-02 15:04") + " 已经过了。要改成明天 " + runAt.Format("15:04") + " 吗？直接回复“明天" + runAt.Format("15:04") + "”即可。"}, nil
		}
		return assistantReminder{Handled: true, Title: title, Reply: reminderQuestionPrefix + "“" + title + "”，但这个时间已经过了。请告诉我未来一年内的日期和时间。"}, nil
	}
	if runAt.After(now.AddDate(1, 0, 0)) {
		return assistantReminder{Handled: true, Title: title, Reply: reminderQuestionPrefix + "“" + title + "”，但这个时间超出了一年。请告诉我未来一年内的日期和时间。"}, nil
	}
	return assistantReminder{Handled: true, Title: title, RunAt: runAt.UTC(), Reply: fmt.Sprintf("已为你创建定时提醒：%s，%s（%s）。你可以在设置页查看；到时会收到站内通知。", title, runAt.Format("2006-01-02 15:04"), timezone)}, nil
}

func (s *Server) insertAssistantReminder(ctx context.Context, tx *sql.Tx, userID, messageID string, plan assistantReminder) error {
	if plan.RunAt.IsZero() {
		return nil
	}
	var active int
	if err := tx.QueryRowContext(ctx, `SELECT COUNT(*) FROM users WHERE id=UNHEX(?) AND status='active'`, userID).Scan(&active); err != nil {
		return err
	}
	if active != 1 {
		return bad(403, "USER_ACCESS_REVOKED", "账号已不可用")
	}
	payload, err := json.Marshal(reminderPayload{Title: plan.Title, Body: "由 AI 助手根据对话创建"})
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, `INSERT INTO scheduled_jobs(id,owner_user_id,job_type,payload,run_at,dedupe_key) VALUES(UNHEX(?),UNHEX(?),'notification.reminder',?,?,?) ON DUPLICATE KEY UPDATE id=id`, id(), userID, payload, plan.RunAt, "assistant-reminder:"+strings.ToLower(messageID))
	return err
}

func (s *Server) savePlannedAssistantReminder(ctx context.Context, conversationID, userID, prompt string, plan assistantReminder) (string, error) {
	tx, err := s.DB.BeginTx(ctx, nil)
	if err != nil {
		return "", err
	}
	defer tx.Rollback()
	var teamID sql.NullString
	if err = tx.QueryRowContext(ctx, `SELECT HEX(team_id) FROM conversations WHERE id=UNHEX(?) AND owner_user_id=UNHEX(?) FOR UPDATE`, conversationID, userID).Scan(&teamID); err != nil {
		return "", err
	}
	if teamID.Valid {
		var active bool
		if err = tx.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM team_memberships m JOIN teams t ON t.id=m.team_id WHERE m.team_id=UNHEX(?) AND m.user_id=UNHEX(?) AND m.status='active' AND t.status='active')`, teamID.String, userID).Scan(&active); err != nil {
			return "", err
		}
		if !active {
			return "", bad(403, "TEAM_ACCESS_REVOKED", "当前团队访问权限已变更")
		}
	}
	messageID, err := saveAIExchangeWithMessageID(ctx, tx, conversationID, userID, prompt, plan.Reply, "teammind", "reminder")
	if err != nil {
		return "", err
	}
	if err = s.insertAssistantReminder(ctx, tx, userID, messageID, plan); err != nil {
		return "", err
	}
	if err = tx.Commit(); err != nil {
		return "", err
	}
	return messageID, nil
}
